from pathlib import Path
import argparse,json,sys,base64
ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,required=True);a=ap.parse_args();r=a.root.resolve();sys.path.insert(0,str(r/'Scripts'));import officer_art_pipeline as g
w=json.loads((r/'Art/Officer/work-record.json').read_text(encoding='utf-8'));p=w['plans'][w['armor_split_page_plan']];g.require_plan(r,p['stage'],p)
spec=json.loads((r/'Art/Officer/ArmorSplitV3/part-definition.json').read_text(encoding='utf-8'));out=r/'Game/Assets/Trials/OfficerArmorSplitV3'
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
assets={name:data(out/(name+'.png')) for name in spec['parts']};assets.update({k:data(r/('Game/Assets/Trials/OfficerEquipmentV2/'+k+'.png')) for k in ['face','hair']});assets['bare_hands_front']=data(out/'bare-hands-front.png');assets['base']=data(r/'Game/Assets/Trials/OfficerBodyBaseV2/body-front.png');assets['source']=data(r/'Game/Assets/Trials/OfficerContextV1/front-64x96.png');occlusion={name:data(out/(name+'-occlusion.png')) for name in spec['parts']}
html="""<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>百代鏡｜甲冑8部位の着脱</title><style>*{box-sizing:border-box}body{margin:0;background:#1d2b33;color:#eee7db;font:16px/1.8 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:24px}h1{font-size:25px}h2{font-size:18px;color:#dfc18c}.row{display:flex;gap:28px;flex-wrap:wrap}.large{width:256px;height:384px;image-rendering:pixelated}.native{width:64px;height:96px;image-rendering:pixelated}canvas{background:repeating-conic-gradient(#bfc0b5 0 25%,#a5a99f 0 50%) 0/16px 16px}button,select{font:inherit;background:#344852;color:inherit;padding:6px 10px;border:1px solid #829397;margin:4px}label{display:inline-block;margin:4px 18px 4px 0}.choices{max-width:340px}.note{border-left:3px solid #d7b57e;padding:10px 16px}.gallery{display:flex;gap:22px;flex-wrap:wrap}a{color:#9ed7e6}details{margin:16px 0}</style><main><h1>甲冑8部位の着脱｜64×96・1倍</h1><p>胴・肩・腕・腰・脚・履物・陣羽織・刀を、元の素体へ同じ座標で重ねています。</p><div class="row"><section><h2>現在・4倍</h2><canvas id="large" class="large" width="64" height="96"></canvas></section><section><h2>元絵・4倍</h2><canvas id="source-large" class="large" width="64" height="96"></canvas></section><section class="choices"><h2>甲冑を表示</h2><div id="armor-options"></div><h2>顔・髪</h2><label><input id="face" type="checkbox" checked>顔・髭</label><label><input id="hair" type="checkbox" checked>髪</label><p><button id="restore">全部戻す</button><button id="armor-off">甲冑を全部外す</button><button id="bare">顔・髪も全部外す</button></p><p>ひとつだけ着ける <select id="solo"><option value="">部位を選択</option></select></p><button data-bg="white">白</button><button data-bg="black">黒</button><button data-bg="checker">市松</button><p id="status">読み込み中…</p></section></div><h2>通常表示・1倍</h2><div class="row"><section><canvas id="native" class="native" width="64" height="96"></canvas><p>現在</p></section><section><canvas id="source-native" class="native" width="64" height="96"></canvas><p>元絵</p></section><section><canvas id="base-native" class="native" width="64" height="96"></canvas><p>保存された素体</p></section></div><h2>8部位の単体・1倍</h2><div class="gallery" id="gallery"></div><p class="note">全装備は元絵の可視画素と一致。顔・髪も全部外すと元の裸素体に一致します。素体PNGは変更していません。各装備の遮蔽は、その装備を外すと解除されます。</p><details><summary>部位の範囲と、元絵で隠れていた面</summary><p>胴は襟・胴の下衣、腕は袖・籠手・手袋、腰は帯・草摺、脚は下衣・腿まわり・臑当て、履物は左右の靴、刀は柄・鍔・鞘を含みます。左右一対はひとつの選択で着脱します。</p><p>陣羽織や肩などを外して見える面は、元絵の可視画素と分けた限定補完です。原画から見えない形を正確に復元したという意味ではありません。無関係な画素を消したり、素体全体を元絵の輪郭で切り抜いたりしていません。</p><p>籠手を外したときは、保存された素手を刀・鞘より手前へ再表示します。正面静止の基準です。歩行・関節の変形・別方向・別装備への交換は未認定。「素体が細すぎて不自然」という外見課題は保留しています。</p></details><p><a href="../../Art/Officer/ArmorSplitV3/validation.json">実画像の検査</a> · <a href="OFFICER_ARMOR_SPLIT_V3.md">制作記録</a> · <a href="officer-equipment-review.html">以前の甲冑一式</a></p><script>"""
html+='const assets='+json.dumps(assets)+';const occlusionAssets='+json.dumps(occlusion)+';const armor='+json.dumps(spec['parts'],ensure_ascii=False)+';const order='+json.dumps(spec['draw_order'])+';'
html+="""const imgs={},masks={},keys=['face','hair',...Object.keys(armor)],selected=new Set(keys);let basePixels;window.armorReady=false;function draw(id,img){let c=document.getElementById(id).getContext('2d');c.clearRect(0,0,64,96);c.imageSmoothingEnabled=false;c.drawImage(img,0,0)}function render(){let c=document.getElementById('large').getContext('2d');c.clearRect(0,0,64,96);let b=new ImageData(new Uint8ClampedArray(basePixels),64,96);for(let name of Object.keys(armor))if(selected.has(name))for(let i=0;i<b.data.length;i+=4)if(masks[name][i]>0)b.data.fill(0,i,i+4);c.putImageData(b,0,0);if(selected.has('face'))c.drawImage(imgs.face,0,0);for(let name of order)if(selected.has(name))c.drawImage(imgs[name],0,0);if(!selected.has('arms'))c.drawImage(imgs.bare_hands_front,0,0);if(selected.has('hair'))c.drawImage(imgs.hair,0,0);draw('native',document.getElementById('large'));for(let k of keys)document.getElementById(k).checked=selected.has(k);let count=Object.keys(armor).filter(k=>selected.has(k)).length;document.getElementById('status').textContent=selected.size===keys.length?'全装備：元絵と画素一致':selected.size===0?'全解除：元の素体と画素一致':'甲冑 '+count+' / 8 部位を表示'}function choose(names){selected.clear();for(let k of names)if(keys.includes(k))selected.add(k);render()}window.armorReview={choose,render,keys};(async()=>{await Promise.all(Object.entries(assets).map(async([k,url])=>{let im=new Image;im.src=url;await im.decode();imgs[k]=im}));const tmp=document.createElement('canvas');tmp.width=64;tmp.height=96;let c=tmp.getContext('2d');c.drawImage(imgs.base,0,0);basePixels=c.getImageData(0,0,64,96).data;for(let [k,url] of Object.entries(occlusionAssets)){let im=new Image;im.src=url;await im.decode();c.clearRect(0,0,64,96);c.drawImage(im,0,0);masks[k]=c.getImageData(0,0,64,96).data}for(let [name,info] of Object.entries(armor)){const l=document.createElement('label'),e=document.createElement('input');e.type='checkbox';e.id=name;e.onchange=()=>{e.checked?selected.add(name):selected.delete(name);render()};l.append(e,info.label);document.getElementById('armor-options').append(l);let o=document.createElement('option');o.value=name;o.textContent=info.label;document.getElementById('solo').append(o);let s=document.createElement('section'),cv=document.createElement('canvas');cv.width=64;cv.height=96;cv.className='native';cv.id='part-'+name;s.append(cv,document.createElement('br'),info.label);document.getElementById('gallery').append(s);draw(cv.id,imgs[name])}for(let k of ['face','hair'])document.getElementById(k).onchange=e=>{e.target.checked?selected.add(k):selected.delete(k);render()};document.getElementById('restore').onclick=()=>{document.getElementById('solo').value='';choose(keys)};document.getElementById('armor-off').onclick=()=>choose(['face','hair']);document.getElementById('bare').onclick=()=>choose([]);document.getElementById('solo').onchange=e=>{if(e.target.value)choose(['face','hair',e.target.value])};document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>document.querySelectorAll('canvas').forEach(c=>c.style.background=b.dataset.bg==='checker'?'':b.dataset.bg==='white'?'white':'#10171c'));draw('source-large',imgs.source);draw('source-native',imgs.source);draw('base-native',imgs.base);render();window.armorReady=true})().catch(e=>{document.getElementById('status').textContent=e.message;throw e});</script></main></html>"""
(r/'Docs/Proposals/officer-armor-parts-review.html').write_text(html,encoding='utf-8');print('ARMOR_REVIEW_READY')
